    TrueMusicJukebox = {
        -- Отключение этого параметра уберет возможность привлечения зомби музыкальным автоматом.
        jukeboxesAttractZombies = true,
        -- Если эта опция включена, песни будут начинаться независимо от того, насколько далеко находятся игроки от их источника, чтобы максимизировать синхронизацию между всеми клиентами в любое время. Однако из-за того, как Zomboid обрабатывает создание звука, клиенты могут на короткое время слегка подвиснуть при старте песен. Если вы отключите эту опцию, клиенты не будут синхронизированы, пока не окажутся в пределах действия музыкального автомата в момент смены треков, но они не будут воспроизводить треки, находящиеся за пределами их слышимой зоны, что уменьшит частоту этих подвисаний.
        ignoreDistanceWhenPlaying = true,
        -- Если на вашем сервере установлена ??программа Lifestyle и эта функция включена, треки Lifestyle отключат звук треков True Music Jukebox, а наши треки отключат звук своих треков. Вы также сможете запускать случайные стили танцев Lifestyle, когда встроенная танцевальная опция Lifestyle недоступна в контекстном меню.
        enableLifestyleIntegrations = false,
        -- Если на вашем сервере установлен Lifestyle и эта функция включена, игроки, танцующие под музыку хотя бы одного звукового музыкального автомата, получат выгоду от эффектов настроения Lifestyle, как будто они слышат свою любимую музыку в исполнении эксперта. Этот эффект возникает только во время танца, чтобы обойти возможный конфликт между доступностью обычной возможности танцевать в Lifestyle и доступностью нашей версии.
        enableLifestyleFavoriteEffects = false,
        -- Если эта функция включена, опция танцев Lifestyle: Hobbies будет скрыта всякий раз, когда игроки не могут слышать музыку из музыкального автомата True Music.
        requireMusicForLifestyleDance = false,
        -- Вынудить игроков использовать 3D аудио эффект, чтобы звук взаимодействовал с комнатами и стенами. По нашему мнению,  так музыка будет звучать хуже, поэтому советуем выключить эту функцию и позволить игрокам самим выбрать предпочтительный звуковой режим основанный на их внутриигровых настройках. По умолчанию, этот мод использует свой собственный звуковой 3D режим.
        forceThreeDimensionalAudio = false,
        -- Если эта опция включена, то вы сможете получить доступ к данным сохраненных местоположений музыкальных автоматов, используя контекстное меню инвентаря своей связки ключей. Взаимодействуйте с любым музыкальным автоматом, чтобы сохранить ключ к его данным для удаленного доступа.
        allowPortableJukeboxKeys = false,
        -- Отключите требование включения музыкальных автоматов. Силы музыки будет достаточно, чтобы поддержать музыкальный автомат.
        disablePowerRequirement = false,
        -- У Героя музыкальных автоматов при его спавне не появляется стартовый набор для сборки музыкального автомата.
        partyPooper = false,
        -- Когда плеер подключается, немедленно отправляйте данные музыкальных автоматов для активных музыкальных автоматов. Сообщалось (на сервере с более чем 150 музыкальными автоматами), что эта функция перегружает серверы с большим населением и большим количеством музыкальных автоматов. Если вашему серверу сложно синхронизировать ваши данные, рассмотрите возможность отключения этой функции или уменьшения максимального значения, указанного ниже.
        requestJukeboxDataOnConnect = true,
        -- Когда игрок подключается, доставляйте только те данные музыкального автомата, которые должны быть слышимы для него. Это может помочь с производительностью. Следовательно, игроки не будут иметь доступа к правильным данным музыкального автомата до тех пор, пока они не получат обновление синхронизации, пока они находятся в той же ячейке, что и музыкальный автомат.
